insert into events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'All About Baby Story Time (0–2 years)','Library-led stories, songs and rhymes for babies ages 0–2 and their caretakers. Specific November 2026 occurrence and Pacific times checked against the official Stockton-San Joaquin County Public Library page on November 6, 2026. Confirm current participation requirements and changes with the library; no place reservation, capacity or image reuse implied.','Mountain House','Mountain House Library Community Room, 201 E Main Street','2026-11-12T10:00:00-08:00','2026-11-12T10:30:00-08:00','Education & community','https://www.ssjcpl.org/events-services/events-calendar/mountain-house/all-about-baby-story-time-0-2yrs2?id=1794506400-232130','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from events where source_url='https://www.ssjcpl.org/events-services/events-calendar/mountain-house/all-about-baby-story-time-0-2yrs2?id=1794506400-232130');
insert into events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'Preschool Storytime','Library-led preschool stories, rhymes and music for children ages 2–5. The page URL contains an older month but the occurrence date explicitly says November 12, 2026. Specific November 2026 occurrence and Pacific times checked against the official Stockton-San Joaquin County Public Library page on November 6, 2026. Confirm current participation requirements and changes with the library; no place reservation, capacity or image reuse implied.','Tracy','Tracy Branch Library — confirm room with library','2026-11-12T10:30:00-08:00','2026-11-12T11:30:00-08:00','Education & community','https://www.ssjcpl.org/events-services/events-calendar/tracy/august-2026/preschool-storytime?id=1794508200-238536','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from events where source_url='https://www.ssjcpl.org/events-services/events-calendar/tracy/august-2026/preschool-storytime?id=1794508200-238536');
insert into events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'Cascada de Flores — La Ofrenda Musical','All-ages bilingual participatory music and dance performance exploring Día de Muertos traditions from Mexico and Central America. Specific November 2026 occurrence and Pacific times checked against the official Stockton-San Joaquin County Public Library page on November 6, 2026. Confirm current participation requirements and changes with the library; no place reservation, capacity or image reuse implied.','Manteca','Manteca Branch Library, 320 W Center Street','2026-11-13T15:30:00-08:00','2026-11-13T16:30:00-08:00','Education & community','https://www.ssjcpl.org/events-services/events-calendar/manteca-branch/cascada-de-flores?id=1794612600-245741','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from events where source_url='https://www.ssjcpl.org/events-services/events-calendar/manteca-branch/cascada-de-flores?id=1794612600-245741');
